def esc(s): return html.escape(s,quote=True)
def t(es,en,tag='p',attrs=''):
 return f'<{tag} data-text-es="{esc(es)}" data-text-en="{esc(en)}" {attrs}>{esc(es)}</{tag}>'
def link(url,es,en,cls='button primary'):
 return t(es,en,'a',f'href="{esc(url)}" class="{cls}"')
def msg(text): return WA+'?text='+quote(text)
