def page(path,title_es,title_en,content):
 markup=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width, initial-scale=1"/><title>{esc(title_es)} | Diez42</title><meta name="description" content="Diez42 en Málaga: clases de español gratis, ayuda a refugiados, curso de empleo para inmigrantes y voluntariado."/><link rel="canonical" href="https://diez42.org/{path}"/><link rel="icon" href="assets/favicon.ico"/><link rel="stylesheet" href="assets/content.css?v={V}"/></head><body>{header}<main id="main-content" class="content-main">{t(title_es,title_en,'h1')}{content}</main>{footer}<script src="assets/content.js?v={V}"></script><script src="assets/site-version.js?v={V}"></script></body></html>'''
 (ROOT/path).write_text(markup)
def video():
 return '<video controls muted playsinline preload="none" poster="assets/videos/Diez42-Futbol-Sala-poster.jpg" width="1280" height="720"><source src="assets/videos/Diez42-Futbol-Sala.mp4" type="video/mp4" />'+link('https://u.pcloud.link/publink/show?code=XZXRaA5ZkU8XJxS8hKyw6picxNHKRYu1PWLX','Ver vídeo','Watch video','text-link')+'</video>'
def community_video(name):
 return f'<video controls muted playsinline preload="none" poster="assets/videos/{name}.jpg"><source src="assets/videos/{name}.mp4" type="video/mp4"/></video>'
def short(p):
 if p['id']=='juegos':return 'Juegos de mesa para divertirte, practicar idiomas y hacer amigos.','Board games to have fun, practise languages and make friends.'
 if p['id']=='empleo':return 'Formación y acompañamiento para buscar trabajo en España.','Training and personal support to find work in Spain.'
 if p['id']=='mariposa':return '[PENDIENTE: descripción]','[PENDIENTE: description]'
 return p['description_es'].split('. ')[0].rstrip('.')+'.',p['description_en'].split('. ')[0].rstrip('.')+'.'
def cards(limit=None):
 result='<div class="content-grid program-list">'
 for p in programs[:limit]:
  es,en=short(p)
  # Existing warm AI-generated wide scenes avoid adding identifiable real visitors.
  image='hero-adult-education.jpg' if p['image'] in ['espanol','ingles','empleo'] else ('hero-food-distribution.jpg' if p['id']=='alimentos' else 'hero-social-support-notes.jpg')
  result+=f'<article class="content-card category-{p["image"]}"><img src="assets/photos/{image}" alt="" width="1672" height="941" loading="lazy"/><div class="card-body">'+t(p['title_es'],p['title_en'],'h2')+t(es,en)+t(p['schedule_es'],p['schedule_en'],'p','class="schedule-label"')+link('programa-'+p['id']+'.html','Saber más','Learn more')+'</div></article>'
 return result+'</div>'
