 content+=t(*expectation)+'<dl class="program-facts">'+t('Horario','Schedule','dt')+t(p['schedule_es'],p['schedule_en'],'dd')+t('Lugar','Place','dt')+t(p['place_es'],p['place_en'],'dd')+t('Responsable','Contact person','dt')+f'<dd>{esc(p["lead"])}</dd></dl>'
