page('quienes-somos.html','Quiénes somos','About us',t('Misión','Mission','h2')+t(*mission)+t('Visión','Vision','h2')+t(*vision)+t(*statement,'blockquote')+f'<p>Asociación para el Desarrollo e Integración Diez42 · CIF G93613776 · Málaga</p><p>{ADDRESS}</p><video controls playsinline preload="metadata" width="848" height="480"><source src="assets/videos/about-diez42.mp4" type="video/mp4"/></video>'+t('Hospitalidad','Hospitality','h2','id="hospitalidad"')+community_video('hospitalidad'))
