def form(kind):
 fields=[('name','Nombre','Name','text'),('email','Email','Email','email'),('phone','Teléfono','Phone','tel'),('languages','Idiomas','Languages','text'),('availability','Disponibilidad','Availability','text'),('interest','Interés / mensaje','Interest / message','textarea')]
 s=t('Completa el formulario para preparar un mensaje. Podrás revisarlo y enviarlo en WhatsApp. El sitio no guarda ni envía estos datos a un servidor.','Fill in the form to prepare a message. You can review and send it in WhatsApp. This site does not store or send these details to a server.')+f'<form data-enquiry="{kind}">'
 for name,es,en,type in fields:
  s+='<label>'+t(es,en,'span')+(f'<textarea name="{name}" rows="4" required></textarea>' if type=='textarea' else f'<input type="{type}" name="{name}" autocomplete="{ {"name":"name","email":"email","phone":"tel"}.get(name,"off") }" required/>')+'</label>'
 s+='<label class="consent"><input type="checkbox" required name="consent"/>'+t('He leído la política de privacidad y acepto compartir estos datos con Diez42 a través de WhatsApp para responder a mi consulta.','I have read the privacy policy and agree to share these details with Diez42 through WhatsApp so my enquiry can be answered.','span')+'</label>'+link('privacy.html','Leer política de privacidad','Read privacy policy','text-link')+t('Preparar mensaje de WhatsApp','Prepare WhatsApp message','button','type="submit" class="button whatsapp-join"')+'<p data-form-result role="status"></p></form>'
 return s
